// Event ورودی WordPress باید سبک باشد: فقط شناسه پست و نوع Event.
// محتوای کامل بعداً از WordPress REST API واکشی می‌شود.
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body ?? req;

const secret = headers['x-wp-webhook-secret'] || headers['x-omid90-webhook-secret'] || '';
const expected = $vars.WORDPRESS_WEBHOOK_SECRET || '';
const authorized = Boolean(expected && secret && secret === expected);

const allowedTypes = new Set(['post.published','post.updated']);
const eventType = String(body.eventType || body.event || '').trim();
const postId = Number(body.postId || body.post_id || body.ID || 0);

const valid = authorized && allowedTypes.has(eventType) && Number.isInteger(postId) && postId > 0;

return [{json:{
  authorized, valid, eventType, postId,
  receivedAt: new Date().toISOString(),
  rawEvent: body
}}];

// نرمال‌سازی Post خام WordPress به مدل استاندارد Article.
// هیچ Adapter پایین‌دستی نباید مستقیماً به ساختار خام WordPress وابسته باشد.
const wp = $input.first().json.body || $input.first().json;
const meta = $('اعتبارسنجی Webhook').first().json;

function stripHtml(html){
  return String(html||'')
    .replace(/<[^>]*>/g,' ')
    .replace(/&nbsp;/g,' ')
    .replace(/&amp;/g,'&')
    .replace(/&#8217;|&#039;/g,"'")
    .replace(/&#8220;|&#8221;|&quot;/g,'"')
    .replace(/\s+/g,' ')
    .trim();
}

const embedded = wp._embedded || {};
const terms = embedded['wp:term'] || [];
const categories = (terms[0]||[]).map(t=>t.name).filter(Boolean);
const tags = (terms[1]||[]).map(t=>t.name).filter(Boolean);
const author = (embedded.author && embedded.author[0] && embedded.author[0].name) || '';
const featuredMedia = embedded['wp:featuredmedia'] && embedded['wp:featuredmedia'][0];
const featuredImage = (featuredMedia && (featuredMedia.source_url || (featuredMedia.media_details && featuredMedia.media_details.sizes && featuredMedia.media_details.sizes.full && featuredMedia.media_details.sizes.full.source_url))) || null;

const article = {
  postId: wp.id,
  title: stripHtml(wp.title && wp.title.rendered),
  content: (wp.content && wp.content.rendered) || '',
  contentText: stripHtml(wp.content && wp.content.rendered),
  excerpt: stripHtml(wp.excerpt && wp.excerpt.rendered),
  url: wp.link,
  featuredImage,
  categories,
  tags,
  author,
  publishedAt: wp.date_gmt ? wp.date_gmt + 'Z' : wp.date,
  modifiedAt: wp.modified_gmt ? wp.modified_gmt + 'Z' : wp.modified
};

// eventId پایدار بر اساس postId + modifiedAt: هر بار محتوای پست واقعاً تغییر کند، Event جدید مجاز است؛
// تکرار همان نسخه (همان modifiedAt) به‌عنوان Duplicate رد می‌شود.
const eventId = `wp:${article.postId}:${article.modifiedAt}`;

return [{json:{
  eventId,
  eventType: meta.eventType,
  entityId: String(article.postId),
  publicationVersion: article.modifiedAt,
  priority: 50,
  receivedAt: meta.receivedAt,
  article
}}];

const event = $('Normalize Article').first().json;
const rows = $input.all().map(i=>i.json).filter(Boolean);
const duplicate = rows.some(r => String(r.event_id || r.eventId) === event.eventId);
return [{json:{...event, duplicate}}];

const e = $('تشخیص تکراری').first().json;
const activeRaw = $vars.ACTIVE_PLATFORMS || 'telegram,bale,eitaa,rubika,x,linkedin';
const platforms = activeRaw.split(',').map(s=>s.trim()).filter(Boolean);

return platforms.map(platform => ({json:{
  job_id: `${e.article.postId}:${platform}:${e.publicationVersion}`,
  event_id: e.eventId,
  event_type: e.eventType,
  platform,
  status: 'pending',
  priority: e.priority,
  attempts: 0,
  max_attempts: 5,
  next_attempt_at: new Date().toISOString(),
  article_json: JSON.stringify(e.article),
  created_at: new Date().toISOString()
}}));
